} from "../constants/GelatoRelay.sol";

abstract contract GelatoRelayBase is GelatoRelayContractsUtils {
    modifier onlyGelatoRelay() {
        require(_isGelatoRelay(msg.sender), "onlyGelatoRelay");
        _;
    }

