","keccak256":"0x915943ad44fcdbb1ec6f026b7ca35da202690defc6171f5a617f1c546682c5ec","license":"MIT"},"contracts/interfaces/IGelato1Balance.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

interface IGelato1Balance {
    event LogUseGelato1Balance(
        address indexed sponsor,
        address indexed target,
        address indexed feeToken,
        uint256 oneBalanceChainId,
        uint256 nativeToFeeTokenXRateNumerator,
        uint256 nativeToFeeTokenXRateDenominator,
        bytes32 correlationId
