pragma solidity 0.8.20;

// solhint-disable func-name-mixedcase
interface IGelatoRelayConcurrentERC2771Base {
    function hashUsed(bytes32 _hash) external view returns (bool);

    function gelato() external view returns (address);

    function CALL_WITH_SYNC_FEE_CONCURRENT_ERC2771_TYPEHASH()
        external
        pure
        returns (bytes32);
}
","keccak256":"0x4e40cdd999462f49a621fe81f0e6309cc94da9185245e61393268c1111166988","license":"MIT"},"contracts/lib/GelatoString.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

library GelatoString {
    function revertWithInfo(
        string memory _error,
        string memory _tracingInfo
    ) internal pure {
        revert(string(abi.encodePacked(_tracingInfo, _error)));
    }

    function prefix(
        string memory _second,
        string memory _first
    ) internal pure returns (string memory) {
        return string(abi.encodePacked(_first, _second));
    }

    function suffix(
        string memory _first,
        string memory _second
    ) internal pure returns (string memory) {
        return string(abi.encodePacked(_first, _second));
    }
}
