","keccak256":"0x915943ad44fcdbb1ec6f026b7ca35da202690defc6171f5a617f1c546682c5ec","license":"MIT"},"contracts/lib/GelatoTokenUtils.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import {NATIVE_TOKEN} from "../constants/Tokens.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {
    SafeERC20
} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

library GelatoTokenUtils {
    function transfer(address _token, address _to, uint256 _amount) internal {
        _token == NATIVE_TOKEN
            ? Address.sendValue(payable(_to), _amount)
            : SafeERC20.safeTransfer(IERC20(_token), _to, _amount);
    }

    function getBalance(
        address token,
        address user
    ) internal view returns (uint256) {
        return
            token == NATIVE_TOKEN
                ? user.balance
                : IERC20(token).balanceOf(user);
    }
}
